128	        Map<Long, Summary> by = new HashMap<>();
129	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
130	            Summary was = by.get(s.getPersonId());
131	            by.put(s.getPersonId(), new Summary(was == null ? 1 : was.count() + 1, s));
132	        }
