138	     * the figure it has now; a claim of theirs that does not count is left unbound.
139	     */
140	    @Transactional
141	    public Person take(String user, String sheetId, Long personId) {
142	        LocalDate today = sheets.today(sheetId);
143	        Person person = people.findByIdAndSheetId(personId, sheetId)
144	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
145	        String grade = person.getGrade();
146	        Snapshot before = rollup.snapshot(sheetId);
147	        BigDecimal total = BigDecimal.ZERO.setScale(2);
148	        boolean fixed = false;
149	        int counted = 0;
150	        for (Claim claim : claims.findBySheetIdAndPersonId(sheetId, personId)) {
151	            if (!counts(claim)) {
152	                claim.unbind();
153	                continue;
154	            }
155	            BigDecimal figure = claimService.figureOf(claim, grade);
156	            fixed |= claim.getSettledDue() != null || claim.isStated();
157	            claim.bind(figure);
158	            counted++;
159	            if (figure != null) {
160	                total = total.add(figure);
161	            }
162	        }
163	        // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
164	        boolean rated = Rate.inForce(rates.findBySheetIdAndGrade(sheetId, grade), today).isPresent();
165	        BigDecimal dueTotal = rated || fixed ? total : null;
166	        claims.flush();
167	        statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted));
168	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
169	                + " due-total=" + (dueTotal != null ? dueTotal.toPlainString() : "n/a")
170	                + " claims=" + counted);
