175	    /** Only OPEN and SETTLED claims count toward what is claimed and due. */
176	    private static boolean counts(Claim claim) {
177	        return claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
