794	/**
795	 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the sheet's
796	 * claimed-total and due-total. A change takes them before it alters anything and hands them back after, and
797	 * every figure it moved is written to the audit after the change's own lines. Called within the change's
798	 * transaction.
799	 */
800	@Service
801	public class RollupService {
802	
803	    /** Shown in place of a due-total whose grade has no rate. */
804	    private static final String NO_RATE = "n/a";
805	
806	    /** A person's figures, as the screen shows them. */
807	    public record Figures(String name, String claimed, String dueTotal) {}
808	
809	    /** The sheet's figures at one moment: each person's by id, in the order they were added, and the totals. */
810	    public record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal) {}
811	
812	    private final PersonRepository people;
813	    private final ClaimRepository claims;
814	    private final RateRepository rates;
815	    private final SheetRepository sheets;
816	    private final Audit audit;
817	
818	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
819	            SheetRepository sheets, Audit audit) {
820	        this.people = people;
821	        this.claims = claims;
822	        this.rates = rates;
823	        this.sheets = sheets;
824	        this.audit = audit;
825	    }
826	
827	    /** The sheet's figures now; none (an empty sheet's) when there is no such sheet. */
828	    public Snapshot snapshot(String sheetId) {
829	        LocalDate today = sheets.findById(sheetId).map(s -> s.getToday()).orElse(null);
830	        Map<Long, List<Claim>> byPerson = new LinkedHashMap<>();
831	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
832	            byPerson.computeIfAbsent(claim.getPersonId(), k -> new ArrayList<>()).add(claim);
833	        }
834	        Map<Long, Figures> figures = new LinkedHashMap<>();
835	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
836	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
837	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
838	            List<Rate> gradeRates = rates.findBySheetIdAndGrade(sheetId, person.getGrade());
839	            List<Claim> counted = byPerson.getOrDefault(person.getId(), List.of()).stream()
840	                    .filter(RollupService::counts).toList();
841	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
842	            BigDecimal due = BigDecimal.ZERO.setScale(2);
843	            boolean frozen = false;
844	            for (Claim claim : counted) {
845	                claimed = claimed.add(claim.getAmount().setScale(2));
846	                frozen |= claim.getSettledDue() != null || claim.isStated();
847	                BigDecimal figure = figureOf(claim, gradeRates);
848	                if (figure != null) {
849	                    due = due.add(figure.setScale(2));
850	                }
851	            }
852	            // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
853	            boolean rated = today != null && Rate.inForce(gradeRates, today).isPresent();
854	            String personDue = rated || frozen ? due.toPlainString() : NO_RATE;
855	            claimedTotal = claimedTotal.add(claimed);
856	            if (rated || frozen) {
857	                dueTotal = dueTotal.add(due);
858	            }
859	            figures.put(person.getId(), new Figures(person.getName(), claimed.toPlainString(), personDue));
860	        }
861	        return new Snapshot(figures, claimedTotal.toPlainString(), dueTotal.toPlainString());
862	    }
863	
864	    /**
865	     * Write to the audit, once the change commits, one ROLLUP line for each person whose figures moved since
866	     * {@code before} (a person new since then counts as moved), in the order they were added, then a TOTALS
867	     * line when the sheet's totals moved.
868	     */
869	    public void recordChanges(String user, String sheetId, Snapshot before) {
870	        claims.flush();
871	        Snapshot after = snapshot(sheetId);
872	        String prefix = " sheet=" + sheetId + " by=" + user;
873	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
874	            Figures now = e.getValue();
875	            Figures was = before.people().get(e.getKey());
876	            if (was != null && was.claimed().equals(now.claimed()) && was.dueTotal().equals(now.dueTotal())) {
877	                continue;
878	            }
879	            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + now.claimed()
880	                    + " due-total=" + now.dueTotal());
881	        }
882	        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
883	                || !Objects.equals(before.dueTotal(), after.dueTotal())) {
884	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
885	                    + " due-total=" + after.dueTotal());
886	        }
887	    }
888	
889	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
890	     * else what is due at its grade's rate; none when that is n/a. */
891	    public BigDecimal figureOf(Claim claim, String grade) {
892	        return figureOf(claim, rates.findBySheetIdAndGrade(claim.getSheetId(), grade));
893	    }
894	
895	    private static BigDecimal figureOf(Claim claim, List<Rate> gradeRates) {
896	        if (claim.getSettledDue() != null) {
897	            return claim.getSettledDue();
898	        }
899	        return claim.isStated() ? claim.getStatedDue() : dueOf(claim, gradeRates);
900	    }
901	
902	    /** What is due on a claim at the rate its grade has in force on the claim's date, rounded half to even to two
903	     * decimals; none when no rate of the grade applies then. */
904	    private static BigDecimal dueOf(Claim claim, List<Rate> gradeRates) {
905	        BigDecimal amount = claim.getAmount();
906	        return Rate.inForce(gradeRates, claim.getDate())
907	                .map(r -> amount.multiply(r.getRate()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
908	                .orElse(null);
909	    }
910	
911	    /** Only OPEN and SETTLED claims count toward what is claimed and due. */
912	    private static boolean counts(Claim claim) {
913	        return claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
914	    }
