811	/**
812	 * The rate a grade has in force on a date (yyyy-mm-dd): the one with the latest from-date on or
813	 * before it; none when the date is before every rate of the grade.
814	 */
815	export function rateOn(rates: readonly Rate[], grade: Grade, date: string): string | undefined {
816	  // No from-date sorts as '', before every date.
817	  let best: Rate | undefined;
818	  for (const r of rates) {
819	    const from = r.from ?? '';
820	    if (r.grade === grade && from <= date && (!best || from > (best.from ?? ''))) best = r;
821	  }
822	  return best?.rate;
