828	/** Hundredths of a decimal with up to two decimals, e.g. "12.5" is 1250. */
829	function hundredths(value: string): bigint {
830	  const [whole, frac = ''] = value.split('.');
831	  return BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
