834	/**
835	 * What is due on an amount at a rate: the amount times the rate, divided by 100, rounded half to
836	 * even to two decimals. Worked in whole numbers so no rounding creeps in; n/a when there is no rate.
837	 */
838	export function dueOf(amount: string, rate: string | undefined): string {
839	  if (rate === undefined) return NO_RATE;
